SELECT order_id, tenant_id, warehouse_id, reference_type, reference_id, status, remark, created_at, updated_at
FROM wms_inbound_order WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY created_at DESC

SELECT order_id, tenant_id, warehouse_id, reference_type, reference_id, status, remark, created_at, updated_at
FROM wms_outbound_order WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY created_at DESC

SELECT movement_id, tenant_id, warehouse_id, seller_sku, from_location_id, to_location_id, quantity, type, reference_type, reference_id, moved_at
FROM wms_inventory_movement WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY moved_at DESC

SELECT check_id, tenant_id, warehouse_id, inbound_order_id, seller_sku, sample_quantity, pass_quantity, fail_quantity, result, inspector, remark, checked_at, created_at
FROM wms_quality_check WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY checked_at DESC

SELECT check_id, tenant_id, warehouse_id, inbound_order_id, seller_sku, sample_quantity, pass_quantity, fail_quantity, result, inspector, remark, checked_at, created_at
FROM wms_quality_check WHERE tenant_id = #{tenantId} AND inbound_order_id = #{inboundOrderId}
ORDER BY checked_at DESC
